import json
import math
import random
import csv
from datetime import datetime, timezone, timedelta

# Load specification generated by live Gemini API
with open("gemini_parsed_spec.json", "r", encoding="utf-8") as f:
    spec = json.load(f)

total_rows = spec.get("totalRows", 10000)
seed = spec.get("seed", 582941)
edge_cases = spec.get("edgeCases", {})

# Mulberry32 PRNG (identical to generatorEngine.ts)
class Mulberry32:
    def __init__(self, s):
        self.s = s & 0xFFFFFFFF
    
    def next(self):
        self.s = (self.s + 0x6D2B79F5) & 0xFFFFFFFF
        t = self.s
        t = math.imul_poly(t ^ (t >> 15), t | 1)
        t ^= (t + math.imul_poly(t ^ (t >> 7), t | 61)) & 0xFFFFFFFF
        return ((t ^ (t >> 14)) & 0xFFFFFFFF) / 4294967296.0

def imul(a, b):
    return ((a & 0xFFFFFFFF) * (b & 0xFFFFFFFF)) & 0xFFFFFFFF

math.imul_poly = imul

prng = Mulberry32(seed)

def next_gaussian(mean=0.0, std_dev=1.0):
    u1 = max(1e-15, prng.next())
    u2 = prng.next()
    z0 = math.sqrt(-2.0 * math.log(u1)) * math.cos(2.0 * math.pi * u2)
    return mean + z0 * std_dev

def pick(lst):
    idx = int(prng.next() * len(lst))
    return lst[min(idx, len(lst) - 1)]

# Targets
fraud_rate = edge_cases.get("fraudRate", 2.0)
fraud_target = round((fraud_rate / 100.0) * total_rows)

extreme_rate = edge_cases.get("extremeValuesRate", 1.0)
extreme_target = round((extreme_rate / 100.0) * total_rows)

missing_rate = edge_cases.get("missingValuesRate", 2.0)
missing_target = round((missing_rate / 100.0) * total_rows)

weekend_uplift = edge_cases.get("weekendSalesIncrease", 30.0)

# Deterministic shuffle for indices
indices = list(range(total_rows))
for i in range(len(indices) - 1, 0, -1):
    j = int(prng.next() * (i + 1))
    indices[i], indices[j] = indices[j], indices[i]

fraud_indices = set(indices[:fraud_target])
extreme_indices = set(indices[fraud_target:fraud_target + extreme_target])
missing_indices = set(indices[fraud_target + extreme_target:fraud_target + extreme_target + missing_target])

records = []
anomaly_logs = []

base_epoch = datetime(2026, 8, 1, 0, 0, 0, tzinfo=timezone.utc)
time_span_seconds = 45 * 24 * 3600

categories = ['electronics', 'fashion', 'home_living', 'beauty_health', 'sports_outdoors']
payment_methods = ['credit_card', 'paypal', 'apple_pay', 'debit_card']
devices = ['mobile_ios', 'mobile_android', 'desktop_mac', 'desktop_windows']
first_names = ['alex', 'sam', 'jordan', 'taylor', 'casey', 'morgan', 'riley', 'cameron']
domains = ['gmail.com', 'yahoo.com', 'outlook.com', 'icloud.com']

weekend_count = 0
weekday_count = 0

for i in range(total_rows):
    row_id = i + 1
    is_fraud = i in fraud_indices
    is_extreme = i in extreme_indices
    is_missing = i in missing_indices
    
    # Timestamp with weekend bias
    sec_offset = int(prng.next() * time_span_seconds)
    sample_dt = base_epoch + timedelta(seconds=sec_offset)
    day_of_week = sample_dt.weekday() # 5 is Sat, 6 is Sun
    is_weekend = day_of_week in (5, 6)
    
    if weekend_uplift > 0 and not is_weekend:
        if prng.next() < (weekend_uplift / 100.0) * 0.28:
            offset_days = 5 - day_of_week
            sample_dt += timedelta(days=offset_days)
            is_weekend = True
            
    if is_weekend:
        weekend_count += 1
    else:
        weekday_count += 1
        
    ts_iso = sample_dt.strftime('%Y-%m-%d %H:%M:%SZ')
    
    # Amount
    base_amount = max(5.0, round(next_gaussian(124.50, 42.0), 2))
    final_amount = base_amount
    
    if is_extreme:
        multiplier = 15.0 + (prng.next() * 35.0)
        final_amount = round(base_amount * multiplier, 2)
        anomaly_logs.append({
            "id": f"anom_{row_id}_extreme",
            "rowId": row_id,
            "type": "EXTREME_VALUE",
            "column": "amount",
            "originalValue": str(base_amount),
            "injectedValue": str(final_amount),
            "severity": "HIGH",
            "reason": f"Outlier injected: {multiplier:.1f}x Gaussian baseline",
            "ruleFormula": f"row['amount'] := base_amount * {multiplier:.1f}"
        })
    elif is_fraud:
        fraud_multiplier = 4.0 + (prng.next() * 6.0)
        final_amount = round(base_amount * fraud_multiplier, 2)
        anomaly_logs.append({
            "id": f"anom_{row_id}_fraud",
            "rowId": row_id,
            "type": "FRAUD_INJECTION",
            "column": "is_fraud",
            "originalValue": "false",
            "injectedValue": "true",
            "severity": "CRITICAL",
            "reason": "Synthetic credit card compromise pattern",
            "ruleFormula": "row['is_fraud'] := true"
        })
        
    # Email
    email_val = f"{pick(first_names)}_{row_id}@{pick(domains)}"
    if is_missing:
        anomaly_logs.append({
            "id": f"anom_{row_id}_missing",
            "rowId": row_id,
            "type": "MISSING_NULL",
            "column": "customer_email",
            "originalValue": email_val,
            "injectedValue": "",
            "severity": "MEDIUM",
            "reason": "Omitted customer contact attribute",
            "ruleFormula": "row['customer_email'] := null"
        })
        email_val = ""
        
    record = {
        "transaction_id": f"tx_{row_id:06d}_{int(prng.next() * 9000 + 1000)}",
        "customer_id": f"cust_{int(prng.next() * 4000 + 1000)}",
        "timestamp": ts_iso,
        "amount": final_amount,
        "payment_method": pick(payment_methods),
        "product_category": pick(categories),
        "device_type": pick(devices),
        "billing_country": pick(['US', 'CA', 'GB', 'DE', 'FR', 'AU', 'IN']),
        "customer_email": email_val,
        "is_fraud": "true" if is_fraud else "false"
    }
    records.append(record)

# Write Dataset CSV
csv_filename = "gemini_generated_ecommerce_10k.csv"
fieldnames = list(records[0].keys())
with open(csv_filename, "w", newline="", encoding="utf-8") as f:
    writer = csv.DictWriter(f, fieldnames=fieldnames)
    writer.writeheader()
    writer.writerows(records)

# Write Anomaly Logs CSV
anom_filename = "gemini_anomaly_audit_log.csv"
with open(anom_filename, "w", newline="", encoding="utf-8") as f:
    writer = csv.DictWriter(f, fieldnames=["id", "rowId", "type", "column", "originalValue", "injectedValue", "severity", "reason", "ruleFormula"])
    writer.writeheader()
    writer.writerows(anomaly_logs)

print(f"SUCCESS: Generated {len(records)} rows from Gemini specification!")
print(f"CSV Dataset: {csv_filename}")
print(f"Anomaly Audit Logs: {anom_filename} ({len(anomaly_logs)} edge-cases injected)")
print(f"Fraud rows: {len(fraud_indices)} ({len(fraud_indices)/total_rows*100:.2f}%)")
print(f"Extreme amount rows: {len(extreme_indices)} ({len(extreme_indices)/total_rows*100:.2f}%)")
print(f"Missing emails: {len(missing_indices)} ({len(missing_indices)/total_rows*100:.2f}%)")
print(f"Weekend distribution: {weekend_count} weekend transactions vs {weekday_count} weekday transactions")
